@Override protected Subtitle decode(byte[] bytes, int length, boolean reset) {
  try {
    parsableByteArray.reset(bytes, length);
    int textLength = parsableByteArray.readUnsignedShort();
    if (textLength == 0) {
      return Tx3gSubtitle.EMPTY;
    }
    String cueText = parsableByteArray.readString(textLength);
    return new Tx3gSubtitle(new Cue(cueText));
  } catch (BufferUnderflowException e) {
    // Handle the case where the byte array is too short
    // For example, log the error or return an empty subtitle
    return Tx3gSubtitle.EMPTY;
  }
}
